type MergeRouters<TRouters extends AnyRouter[]> = {
  [TKey in keyof TRouters]: TRouters[TKey] extends AnyRouter
    ? {
        [TProcedure in keyof TRouters[TKey]['_def']['procedures']]: TRouters[TKey]['_def']['procedures'][TProcedure] extends {
          _type: ProcedureType;
        }
          ? {
              input: inferProcedureInput<TRouters[TKey]['_def']['procedures'][TProcedure]>;
              output: inferProcedureOutput<TRouters[TKey]['_def']['procedures'][TProcedure]>;
            }
          : never;
      }
    : never;
};

export function mergeRouters<TRouters extends AnyRouter[]>(...routerList: [...TRouters]): MergeRouters<TRouters> {
  return routerList.reduce((acc, router) => {
    for (const [key, procedure] of Object.entries(router._def.procedures)) {
      if (acc[key]) {
        throw new Error(`Duplicate procedure name: ${key}`);
      }
      acc[key] = {
        input: procedure.input,
        output: procedure.output,
      };
    }
    return acc;
  }, {} as MergeRouters<TRouters>);
}

