import { AnyRouter, ProcedureType, inferProcedureInput, inferProcedureOutput, inferProcedureContext, inferProcedureMeta } from '@trpc/server';
import { IntersectionError } from '@trpc/server/src/error/formatter';
import { mergeMiddlewares } from '@trpc/server/src/core/internals/mergeMiddlewares';
import { mergeMeta } from '@trpc/server/src/core/internals/mergeMeta';
import { mergeErrorFormatters } from '@trpc/server/src/core/internals/mergeErrorFormatters';

type MergeRouters<TRouters extends AnyRouter[]> = {
  [TKey in keyof TRouters]: TRouters[TKey] extends AnyRouter ? TRouters[TKey] : never;
}[number];

export function mergeRouters<TRouters extends AnyRouter[]>(...routerList: [...TRouters]): MergeRouters<TRouters> {
  const procedures: Record<string, any> = {};

  for (const router of routerList) {
    for (const [key, procedure] of Object.entries(router._def.procedures)) {
      if (procedures[key]) {
        throw new IntersectionError(`Duplicate procedure: ${key}`);
      }
      procedures[key] = procedure;
    }
  }

  const middlewares = mergeMiddlewares(routerList.map((router) => router._def.middlewares));
  const meta = mergeMeta(routerList.map((router) => router._def.meta));
  const errorFormatter = mergeErrorFormatters(routerList.map((router) => router._def.errorFormatter));

  return {
    _def: {
      procedures,
      middlewares,
      meta,
      errorFormatter,
    },
  } as any;
}

